  /// 클레임번호(이슈 #107) — `C` + YYMMDD(KST) + 숫자 8자리. 취소·반품·교환 접수 단위 번호이고 생성 후 바뀌지 않습니다.
  String? get claimNo => _j['claimNo'] as String?;

  /// `type` 값입니다.
  String get type => _j['type'] as String;

  /// `status` 값입니다.
  String get status => _j['status'] as String;

  /// `orderItemId` 값입니다.
  String get orderItemId => _j['orderItemId'] as String;

  /// `productName` 값입니다.
  String get productName => _j['productName'] as String;

  /// 접수된 수량.
  int get quantity => _j['quantity'] as int;

  /// `reason` 값입니다.
  String get reason => _j['reason'] as String;

  /// 예상 환불액 — 수량 비율 상품 실결제 금액 − 반품 배송비 − 조건부 무료배송 미달 차감 − 쿠폰 조건 미달 차감 + 되돌릴 쿠폰 차감. **배송비 환불은 포함되지 않고 `expectedDeliveryFeeRefundAmount`로 따로 옵니다.** 교환은 null입니다.
  int? get expectedRefundAmount => _j['expectedRefundAmount'] as int?;

  /// 예상 배송비 환불액. 배송 묶음이 모두 취소되거나 판매자 귀책일 때만 0보다 큽니다. 이 필드가 생기기 전에 접수된 클레임은 null입니다.
  int? get expectedDeliveryFeeRefundAmount => _j['expectedDeliveryFeeRefundAmount'] as int?;

  /// 예상 반환 적립금 (원, #93) — 결제에 쓴 적립금 중 이 수량의 몫입니다. 예상 환불액(현금)과 별개이고, 차감은 현금에서 먼저 뺍니다. 교환·적립금을 쓰지 않은 주문은 0입니다. 서버는 항상 싣습니다.
  int get expectedPointRefundAmount => _j['expectedPointRefundAmount'] as int;

  /// `rejectReason` 값입니다.
  String? get rejectReason => _j['rejectReason'] as String?;

  /// 반품·교환 물건을 보낼 반품지(이슈 #30). 직접 보내는 수거 안내에 씁니다. 취소 클레임은 null.
  ClaimReturnAddress? get returnAddress => _j['returnAddress'] as ClaimReturnAddress?;

  /// `requestedAt` 값입니다.
  String get requestedAt => _j['requestedAt'] as String;

  /// `completedAt` 값입니다.
  String? get completedAt => _j['completedAt'] as String?;
}
